type SearchArgs = InferArgs<typeof SEARCH_PARAMETERS>

/** One primary or supplemental hit; shared by the paged list and the note-body supplement. */
const SEARCH_ITEM_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    ref: { type: 'string', required: true },
    title: { type: 'string', required: true },
    creatorSummary: { type: 'string', required: true },
    authors: { type: 'array', items: { type: 'string' } },
    venue: { type: 'string' },
    year: { type: 'integer' },
    itemType: { type: 'string', required: true },
    parentRef: { type: 'string' },
    bestAttachmentRef: { type: 'string' },
    bestAttachmentType: { type: 'string' },
    attachmentSize: { type: 'integer' },
    extra: { type: 'string' },
    citationKey: { type: 'string' },
    citationKeySource: { type: 'string', enum: ['native', 'extra'] },
    citationKeyConflict: {
      type: 'object',
      additionalProperties: false,
      properties: {
        native: { type: 'string', required: true },
        extra: { type: 'string', required: true },
      },
    },
    doi: { type: 'string' },
  },
} as const

type AssertNever<T extends never> = T
type InferredSearchItem = InferValue<typeof SEARCH_ITEM_SCHEMA>

type MissingInSearchItemSchema = Exclude<keyof ZoteroSearchItem, keyof InferredSearchItem>
type ExtraInSearchItemSchema = Exclude<keyof InferredSearchItem, keyof ZoteroSearchItem>

// Compile-time pins: fails build if ZoteroSearchItem and SEARCH_ITEM_SCHEMA drift
declare const _searchItemSchemaComplete: AssertNever<MissingInSearchItemSchema>
declare const _searchItemSchemaNoExtra: AssertNever<ExtraInSearchItemSchema>

const SEARCH_OUTPUT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    scope: {
      required: true,
      oneOf: [
        // The personal library is always the canonical user/0; a group id
        // is any positive integer. The nested union matches SupportedLocalLibrary.
        {
          type: 'object',
          additionalProperties: false,
          properties: {
            kind: { type: 'string', const: 'library', required: true },
            library: {
              required: true,
              oneOf: [
                {
                  type: 'object',
                  additionalProperties: false,
                  properties: {
                    type: { type: 'string', const: 'user', required: true },
                    id: { type: 'integer', const: 0, required: true },
                  },
                },
                {
                  type: 'object',
                  additionalProperties: false,
                  properties: {
                    type: { type: 'string', const: 'group', required: true },
                    id: { type: 'integer', required: true },
                  },
                },
              ],
            },
          },
        },
        {
          type: 'object',
          additionalProperties: false,
          properties: {
            kind: { type: 'string', const: 'publications', required: true },
            library: {
              type: 'object',
              required: true,
              additionalProperties: false,
              properties: {
                type: { type: 'string', const: 'user', required: true },
                id: { type: 'integer', const: 0, required: true },
              },
            },
          },
        },
        {
          type: 'object',
          additionalProperties: false,
          properties: {
            kind: { type: 'string', const: 'collection', required: true },
            ref: { type: 'string', required: true },
            name: { type: 'string', required: true },
          },
        },
        {
          type: 'object',
          additionalProperties: false,
          properties: {
            kind: { type: 'string', const: 'savedSearch', required: true },
            ref: { type: 'string', required: true },
            name: { type: 'string', required: true },
          },
        },
      ],
    },
    items: {
      type: 'array',
      required: true,
      items: SEARCH_ITEM_SCHEMA,
    },
    total: { type: 'integer', required: true },
    offset: { type: 'integer', required: true },
    returned: { type: 'integer', required: true },
    maximum: { type: 'integer' },
    normalizedQuery: { type: 'string' },
    queryWasEmpty: { type: 'boolean' },
    nextActions: { type: 'array', items: { type: 'string' } },
    nextOffset: { type: 'integer' },
    supplemental: {
      type: 'object',
      additionalProperties: false,
      properties: {
        kind: { type: 'string', const: 'noteBody', required: true },
        items: { type: 'array', required: true, items: SEARCH_ITEM_SCHEMA },
        scanned: { type: 'integer', required: true },
        truncated: { type: 'boolean', required: true },
      },
    },
  },
} as const

/** The model-facing messages the search argument rules throw. */
export const SCOPE_REF_OR_NAME_MESSAGE =
  'scope.refOrName must be a collection/saved-search name or ref'
export const TAGS_LITERAL_MESSAGE =
  'tags are literal tag names (AND semantics); got an empty or "||"-containing tag'
export const EXCLUDE_TAGS_LITERAL_MESSAGE = 'excludeTags are literal tag names'
export const TAG_MATCH_REQUIRES_TAGS_MESSAGE =
  'tagMatch requires tags; it has no effect without a tag filter'
export const ITEM_TYPES_LITERAL_MESSAGE =
  'itemTypes are positive Zotero item type names joined with OR'

export function searchLimitMessage(requested: number, maximum: number): string {
  return `limit must be an integer between 1 and ${maximum}; got ${requested}. Set limit <= ${maximum} and use offset for the next page.`
}

/** The page announcement: where the next page starts, and that the scope stays. */
export function searchMoreMessage(nextOffset: number): string {
  return `More results available: search again with offset ${nextOffset} and the same scope.`
}

/** The supplemental announcement: note-body matches sit outside the paged total. */
export function noteBodyMatchesMessage(count: number, scanned: number, truncated: boolean): string {
  return `+${count} note-body matches (scanned ${scanned}${truncated ? '+' : ''} notes, ordered by dateModified desc, outside the paged total):`
}

function buildRequest(args: SearchArgs, config: ResolvedConfig): ZoteroSearchRequest {
  const limit = args.limit ?? SEARCH_DEFAULT_LIMIT
  if (!Number.isInteger(limit) || limit < 1 || limit > config.maxSearchResults) {
    invalidArgs(searchLimitMessage(limit, config.maxSearchResults))
  }
  const offset = args.offset ?? SEARCH_DEFAULT_OFFSET
  assertIntInRange('offset', offset, 0, 1_000_000)
  const query = args.query?.trim()
  const scope = args.scope ?? SEARCH_DEFAULT_SCOPE
  if (scope.kind !== 'library' && scope.kind !== 'publications' && scope.refOrName.trim() === '') {
    invalidArgs(SCOPE_REF_OR_NAME_MESSAGE)
  }
  for (const tag of args.tags ?? []) {
    if (!isLiteralSearchTag(tag)) {
      invalidArgs(`${TAGS_LITERAL_MESSAGE}: "${tag}"`)
    }
  }
  for (const tag of args.excludeTags ?? []) {
    if (!isLiteralSearchTag(tag)) {
      invalidArgs(`${EXCLUDE_TAGS_LITERAL_MESSAGE}; got "${tag}"`)
    }
  }
  // tagMatch's all|any enum is enforced by the parameter schema; the
  // cross-field rule below is what the schema cannot express.
  const tagMatch = args.tagMatch
  if (tagMatch !== undefined && (args.tags === undefined || args.tags.length === 0))
    invalidArgs(TAG_MATCH_REQUIRES_TAGS_MESSAGE)
  for (const itemType of args.itemTypes ?? []) {
    if (!isItemTypeIdentifier(itemType)) {
      invalidArgs(`${ITEM_TYPES_LITERAL_MESSAGE}; got "${itemType}"`)
    }
  }
  const library = parseLibrary(args.library)
  if (scope.kind === 'publications') {
    assertPublicationsSupported(library)
  }
  return {
    query: query === '' ? undefined : query,
    mode: args.mode ?? SEARCH_DEFAULT_MODE,
    scope:
      scope.kind === 'library'
        ? { kind: 'library' }
        : scope.kind === 'publications'
          ? { kind: 'publications' }
          : { kind: scope.kind, refOrName: scope.refOrName },
    ...(library ? { library } : {}),
    itemTypes: args.itemTypes,
    tags: args.tags,
    ...(tagMatch ? { tagMatch } : {}),
    ...(args.excludeTags ? { excludeTags: args.excludeTags } : {}),
    itemLevel: args.itemLevel ?? 'top',
    sort: args.sort ?? SEARCH_DEFAULT_SORT,
    direction: args.direction ?? SEARCH_DEFAULT_DIRECTION,
    offset,
    limit,
  }
}

/** One search hit as the model reads it: ref line plus citekey, creators, and PDF hint. */
function formatSearchResultLine(
  item: SearchOutput['items'][number],
  index: number,
  withPdfHint: boolean,
): string {
  const citekey = item.citationKey
  const citeTag = citekey ? ` [@${citekey}]` : ''
  const conflict = item.citationKeyConflict
  const conflictTag = conflict
    ? ` [citation key conflict: ${formatCitationKeyConflict(conflict)}]`
    : ''
  const creator = item.creatorSummary === '' ? '' : ` — ${item.creatorSummary}`
  const pdf = withPdfHint && isPdfContentType(item.bestAttachmentType) ? ' — PDF' : ''
  return `${index + 1}. ${formatSearchLine(item.ref, item.title, item.year, item.itemType)}${citeTag}${conflictTag}${creator}${pdf}`
}

export function renderSearch(_args: SearchArgs, value: SearchOutput): ContentBlock[] {
  const lines = [`Found ${value.returned} of ${value.total} results:`]
  if (value.returned === 0) {
    lines.push(
      `No matches. ${value.nextActions?.join('; ') ?? 'Try a DOI, shorten the title, or add an author surname.'}.`,
    )
  }
  value.items.forEach((item, index) => {
    lines.push(formatSearchResultLine(item, index, true))
  })
  if (value.nextOffset !== undefined) {
    lines.push(searchMoreMessage(value.nextOffset))
  }
  const supplemental = value.supplemental
  if (supplemental !== undefined && supplemental.items.length > 0) {
    lines.push(
      noteBodyMatchesMessage(
        supplemental.items.length,
        supplemental.scanned,
        supplemental.truncated,
      ),
    )
    supplemental.items.forEach((item, index) => {
      lines.push(formatSearchResultLine(item, index, false))
    })
  }
  return [{ type: 'text', text: lines.join('\n') }]
}

/** Replayable projection: page facts plus the bounded rows the Zotero tab lists. */
function searchPresentationMeta(_args: SearchArgs, value: SearchOutput): JsonValue {
  return boundedPresentationMeta(projectSearchMeta(value), ['items'])
}

/**
 * The completed search card: a compact page summary. `meta` is absent on
 * nested code dispatch or malformed replay records, and a failed call keeps
 * the raw error content; both fall back to the generic card.
 */
function presentSearchResult(_args: SearchArgs, result: ToolResult): ToolResultView | undefined {
  const record = metaRecordOf(result)
  if (record === undefined) return undefined
  if (typeof record.returned !== 'number' || typeof record.total !== 'number') return undefined
  const noteMatches = typeof record.noteMatches === 'number' ? record.noteMatches : 0
  return {
    card: 'generic',
    title: `Zotero search: found ${record.returned} of ${record.total} results${noteMatches > 0 ? ` (+${noteMatches} note matches)` : ''}`,
  }
}

/**
 * Register the `zotero_search` tool. The service's live config is read per
 * request so a settings edit takes effect on the next call without
 * re-registration.
 * @param ctx - the plugin context.
 * @param service - the zotero service owning the request path.
 */
export function registerSearchTool(
  ctx: Context,
  service: ZoteroService,
  wrap: ToolWrapper = identityToolWrapper,
): void {
  ctx.tools.register(
    wrap(
      defineTool({
        name: 'zotero_search',
        description: [
          "Search the user's local Zotero research library for candidate papers.",
          'metadata mode matches titles, creators, and years; everything mode also searches indexed full text.',
          'On the first page of a library or collection scope (saved-search scopes never scan note bodies), a client-side note-body scan lists matching notes separately in supplemental; they fill unused page slots up to the limit, are ordered by dateModified desc, never displace a full primary result page, and are not part of the paged total/nextOffset; notes show a synthesized title from their first line.',
          "scope restricts the search to a collection or a Zotero saved search by name or zotero:// ref; additional filters combine with a saved search's own conditions.",
          'Results carry stable zotero:// refs for zotero_get/zotero_retrieve, and a scope ref for pagination via offset.',
        ].join(' '),
        parameters: SEARCH_PARAMETERS,
        output: {
          schema: SEARCH_OUTPUT_SCHEMA,
          render: renderSearch,
          presentationMeta: searchPresentationMeta,
        },
        presentCall: (args) => ({
          card: 'generic',
          kind: 'search',
          title: 'Search Zotero library',
          rawInput: args.query ?? '(browse)',
        }),
        presentResult: presentSearchResult,
        isConcurrencySafe: () => true,
        async execute(args, exec) {
          const request = buildRequest(args, service.config)
          const result = await service.search(
            request,
            exec.signal,
            // The model consumes the note-body supplement.
            { includeSupplemental: true },
          )
          return {
            ...result,
            maximum: service.config.maxSearchResults,
            scope: toolScopeOf(result.scope),
          }
        },
      }),
    ),
  )
}
